1140:             return Err(CoreError {
1141:                 message: format!("unknown alias '{alias}'"),
1142:                 line: 1,
1143:                 column: 1,
1144:                 origin: None,
1145:                 name_resolution: false,
1146:             });
1147:         }
1148:         Ok(QualifiedName {
1149:             namespace: None,
1150:             name: prefix(&alias, &qualified.name),
1151:         })
1152:     } else {
